const refreshMapBeforeExpansion=refreshMap;refreshMap=function(){refreshMapBeforeExpansion();enhanceMapView();};
const publicWorldBeforePruning=publicWorld;publicWorld=function(secrets=false,canon=false){const w=publicWorldBeforePruning(secrets,canon);const ids=new Set(w.entries.map(e=>e.id)),docs=new Set(w.documents.map(d=>d.id));for(const d of w.documents){d.links=d.links.filter(id=>ids.has(id));d.branches=d.branches.filter(b=>docs.has(b.targetId));}for(const m of w.maps)m.objects=m.objects.filter(o=>!o.entryId||ids.has(o.entryId));for(const e of w.entries){e.accounts=e.accounts.filter(a=>secrets||a.kind==='Established'&&!a.knownBy.length);e.lifeStages.forEach(s=>s.links=s.links.filter(id=>ids.has(id)));}if(!secrets){w.questions=[];w.boards=[];w.plotThreads=[];const used=new Set(w.entries.flatMap(e=>e.references));for(const m of w.maps){if(m.background)used.add(m.background);Object.values(m.customSources||{}).forEach(id=>used.add(id));m.objects.forEach(o=>{if(o.assetId)used.add(o.assetId);});}w.assets=w.assets.filter(a=>used.has(a.id));}return w;};
Object.assign(window.JagoWorld,{makeStarter,makeMap,generateAdvanced,validateProject,mapSVG,pngMap,bible,publicWorld,saveProject,generateSpaceMap,generateCityMap,installGeneratedMap,coastToggle,arrangeMapLabels,mapChecks,upgradeWorld,characterSVG,dateOrdinal,dateLabel,drainageGrid,referenceBundle});
window.JagoWorld.expansion={get theme(){return world?.appTheme;},setYear(y){worldYear=mapYear=y;render();},setPlayback(on){mapPlayback=on;render();},setTime(t){mediaClock=t;},get version(){return WORLD_VERSION;}};
const helpBeforeExpansion=help;help=function(){helpBeforeExpansion();$('#dialogBody')?.insertAdjacentHTML('beforeend',`<hr><h3>Room to build</h3><p>Map styles change the artwork, symbols and typography. App themes change your desk. Use Generate for worlds, cities, interiors or star systems, then edit freely. Map checks offer suggestions; they never block your choices.</p><p>Edit coastlines creates editable land shapes. Show generated geography takes you back, and your edits stay ready for next time. Height and biome views help explain the geography.</p><p>Link detail maps to locations: a world, its cities, a tavern, or a spaceship and its rooms. Play preview brings animated artwork and object motion to life. Export offers still images, loop frames, GIF or supported video formats.</p><p>Character histories, world dates, beliefs, story threads and open questions help you connect the people to the places. Reference packs let you choose what readers receive. Send to studio carries artwork and loops between the four Jago tools.</p><p><strong>Open source. Free forever.</strong></p>`);};
